<script lang="ts">import {createComboboxController} from "@civaria/core";import {normalizeSvelteProps} from "./internal.js";type Item={value:string;label?:string;disabled?:boolean};let {items=[],value=$bindable(""),inputValue=$bindable(""),placeholder="",name,required=false,disabled=false,id="civ-combobox"}=$props<{items?:Item[];value?:string;inputValue?:string;placeholder?:string;name?:string;required?:boolean;disabled?:boolean;id?:string}>();const controller=createComboboxController({id,defaultValue:value,defaultInputValue:inputValue,onValueChange:next=>value=next,onInputValueChange:next=>inputValue=next});controller.setItems(items);let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{controller.setItems(items);if(value!==state.value)controller.syncValue(value);if(inputValue!==state.inputValue)controller.syncInputValue(inputValue)});function p(kind:"root"|"input"|"content"|"item"|"hiddenInput",index=0){state;if(kind==="root")return normalizeSvelteProps(controller.getRootProps());if(kind==="input"){const out=normalizeSvelteProps(controller.getInputProps());return {...out,disabled:disabled||undefined,required:required||undefined,"aria-required":required||undefined}}if(kind==="content")return normalizeSvelteProps(controller.getContentProps());if(kind==="hiddenInput")return normalizeSvelteProps(controller.getHiddenInputProps(name,required,disabled));return normalizeSvelteProps(controller.getItemProps(index))}</script><div {...p("root")} class="civ-combobox"><input {...p("input")} class="civ-combobox__input" {placeholder} value={state.inputValue} oninput={(event)=>controller.setInputValue(event.currentTarget.value)} /><div {...p("content")} class="civ-combobox__content">{#each items as item,index (item.value)}<div {...p("item",index)} class="civ-combobox__item">{item.label??item.value}</div>{/each}</div><input {...p("hiddenInput")} class="civ-combobox__hiddenInput" /></div>
